package com.termux.app.workspace;

import android.app.*;import android.content.res.*;import android.os.Looper;import android.view.*;import android.widget.*;
import com.termux.app.TermuxActivity;import com.termux.R;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentManagerLayoutTest {
 TermuxActivity a;AgentInstructionsUi.Editor instructions;AgentSkillsUi.Screen skills;
 @Before public void setup(){a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);}
 @After public void close(){if(instructions!=null)instructions.dialog.dismiss();if(skills!=null)skills.dialog.dismiss();Shadows.shadowOf(Looper.getMainLooper()).idle();a.finish();}
 void await(boolean editor)throws Exception{for(int i=0;i<150;i++){Shadows.shadowOf(Looper.getMainLooper()).idle();if(editor?!instructions.busy:!skills.busy)return;Thread.sleep(10);}fail("async operation timeout");}
 JSONObject read(JSONObject q)throws Exception{return new JSONObject().put("text","line\n".repeat(90)).put("path","/actual/codex/AGENTS.md").put("revision","one").put("exists",true).put("templateAvailable",false).put("projectSource","/project/AGENTS.md");}
 void editor()throws Exception{instructions=new AgentInstructionsUi.Editor(a,"/project",this::read);instructions.show();await(true);}
 void list()throws Exception{skills=new AgentSkillsUi.Screen(a,"/project","codex");skills.backend=q->{JSONArray rows=new JSONArray();for(int i=0;i<80;i++)rows.put(new JSONObject().put("name","sample-"+i).put("path","/actual/home/.agents/skills/"+i).put("description","Long fixture description\nsecond line"));return new JSONObject().put("skills",rows).put("target","/actual/home/.agents/skills").put("roots",new JSONArray().put(new JSONObject().put("path","/actual/home/.agents/skills").put("scope","user")).put(new JSONObject().put("path","/actual/custom/codex/skills").put("scope","legacy")).put(new JSONObject().put("path","/project/.agents/skills").put("scope","project")));};skills.show();await(false);}
 void config(String lang,float scale){WorkspaceLanguage.select(a,lang);Resources r=a.getResources();Configuration c=new Configuration(r.getConfiguration());c.fontScale=scale;r.updateConfiguration(c,r.getDisplayMetrics());r.getDisplayMetrics().scaledDensity=r.getDisplayMetrics().density*scale;}
 int verticals(View v){int n=v instanceof ScrollView?1:0;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)n+=verticals(((ViewGroup)v).getChildAt(i));return n;}
 void measure(View v,int width,int height){v.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));v.layout(0,0,width,height);}
 void verify(AgentManagerLayout frame,int width,int height){measure(frame,width,height);assertEquals("one vertical scroll",1,verticals(frame));assertTrue(frame.header.getHeight()>0);assertTrue(frame.scroll.getHeight()>0);assertTrue(frame.footer.getHeight()>0);assertEquals("only standard 6dp gap",frame.scroll.getBottom()+WorkspaceDialogs.dp(a,6),frame.footer.getTop());assertTrue(frame.footer.getBottom()<=height);for(int i=0;i<frame.footer.getChildCount();i++){View v=frame.footer.getChildAt(i);assertTrue(v.getHeight()>0);assertTrue(v.getLeft()>=0&&v.getRight()<=frame.footer.getWidth());assertTrue(v.getBottom()<=frame.footer.getHeight());}int headerTop=frame.header.getTop(),footerTop=frame.footer.getTop();frame.scroll.fullScroll(View.FOCUS_DOWN);assertTrue(frame.scroll.getScrollY()>0);assertEquals(headerTop,frame.header.getTop());assertEquals(footerTop,frame.footer.getTop());}
 @Test public void bothManagersUseOneViewportAndKeepFooterInReducedImeSpace()throws Exception{
  for(String lang:new String[]{"ru","en"})for(float scale:new float[]{1f,1.6f}){
   config(lang,scale);editor();list();for(int width:new int[]{280,320})for(int height:new int[]{360,580}){verify(instructions.frame,width,height);verify(skills.frame,width,height);assertTrue(instructions.editor.getHeight()>instructions.frame.scroll.getHeight());assertEquals(Integer.MAX_VALUE,instructions.editor.getMaxLines());assertFalse(instructions.editor.canScrollVertically(1));}
   instructions.dialog.dismiss();skills.dialog.dismiss();Shadows.shadowOf(Looper.getMainLooper()).idle();instructions=null;skills=null;
  }
 }
 @Test public void shortEditorExpandsToEndOfViewportInsteadOfLeavingBlankBand()throws Exception{
  config("ru",1);editor();instructions.editor.setText("short");measure(instructions.frame,360,700);android.graphics.Rect b=new android.graphics.Rect();instructions.editor.getDrawingRect(b);instructions.frame.content.offsetDescendantRectToMyCoords(instructions.editor,b);assertTrue("editor ends with scroll content",instructions.frame.content.getHeight()-b.bottom<=12);assertTrue(instructions.editor.getHeight()>instructions.dp(120));
 }
 @Test public void keyboardWindowPolicyIsResizeWithoutPixelScreenHeight()throws Exception{editor();list();for(Dialog d:new Dialog[]{instructions.dialog,skills.dialog}){int mode=d.getWindow().getAttributes().softInputMode;assertEquals(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE,mode&WindowManager.LayoutParams.SOFT_INPUT_MASK_ADJUST);assertEquals(0,d.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_ALT_FOCUSABLE_IM);assertTrue(d.getWindow().getAttributes().height<0);}}
 @Test public void nativeAlertContainerKeepsTitleAndContentWhenWindowShrinks()throws Exception{
  config("ru",1.6f);editor();list();
  for(int height:new int[]{400,620})for(Dialog d:new Dialog[]{instructions.dialog,skills.dialog}){View decor=d.getWindow().getDecorView();measure(decor,320,height);AgentManagerLayout frame=d==instructions.dialog?instructions.frame:skills.frame;assertTrue("native dialog must allocate a scroll viewport",frame.scroll.getHeight()>0);android.graphics.Rect footer=new android.graphics.Rect();frame.footer.getDrawingRect(footer);((ViewGroup)decor).offsetDescendantRectToMyCoords(frame.footer,footer);assertTrue("buttons within native window",footer.bottom<=height);assertTrue("title remains in native chrome",allText(decor).contains(d==instructions.dialog?"Инструкции агентов":"Навыки агентов"));}
 }
 @Test public void feedbackIsRevealedWithoutChangingTheDraft()throws Exception{
  config("ru",1);editor();AgentManagerLayout frame=instructions.frame;measure(frame,320,500);frame.scroll.fullScroll(View.FOCUS_DOWN);assertTrue(frame.scroll.getScrollY()>0);String draft=instructions.editor.getText().toString();instructions.status.setText("Не удалось сохранить. Черновик сохранён в редакторе.");measure(frame,320,500);Shadows.shadowOf(Looper.getMainLooper()).idle();android.graphics.Rect bounds=new android.graphics.Rect();instructions.status.getDrawingRect(bounds);frame.content.offsetDescendantRectToMyCoords(instructions.status,bounds);assertTrue(bounds.bottom>frame.scroll.getScrollY());assertTrue(bounds.top<frame.scroll.getScrollY()+frame.scroll.getHeight());assertEquals(draft,instructions.editor.getText().toString());
 }
 String allText(View v){String s=v instanceof TextView?((TextView)v).getText().toString():"";if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s+="\n"+allText(((ViewGroup)v).getChildAt(i));return s;}
 @Test public void sharedSkillsShowActualRootsAndHideProjectPicker()throws Exception{config("ru",1);list();assertFalse(allText(skills.selectors).contains("Папка проекта"));String rows=allText(skills.rows);assertTrue(rows.contains("/actual/home/.agents/skills"));assertTrue(rows.contains("/actual/custom/codex/skills"));assertFalse(rows.contains("/project/.agents/skills"));TextView project=(TextView)((LinearLayout)((HorizontalScrollView)skills.frame.header.getChildAt(0)).getChildAt(0)).getChildAt(1);project.performClick();await(false);assertEquals("project",skills.scope);assertTrue(allText(skills.selectors).contains("Папка проекта"));assertTrue(((LinearLayout)((HorizontalScrollView)skills.frame.header.getChildAt(0)).getChildAt(0)).getChildAt(1).isSelected());}
}
